	/**
	 * Diary bits, skill targets and quest vars all flip the moment the work is
	 * done, so waiting for the next login would leave a finished step un-ticked.
	 *
	 * <p>Quest completion is the exception: it is deferred to the next game tick
	 * because this runs inside a client script, where Quest.getState is not
	 * allowed.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// Batch the guide-wide completion sweeps on GameTick. A burst of
		// var updates otherwise scans every step repeatedly on the client thread.
		// Most doors replace their scene object when opened, but an impostor can
		// also change its actions in place when a varbit flips. The route's cached
		// Open/Slash scan is rebuilt only if a tracked definition actually changes.
		pathTracker.onVariablesChanged();
		sceneTracker.onVariablesChanged();
		questCheckPending = true;
	}

	/** Resolve explicit guide-bank searches after Bank Tags' default-priority filter. */
	@Subscribe(priority = -1)
	public void onScriptCallbackEvent(net.runelite.api.events.ScriptCallbackEvent event)
	{
		if (!"bankSearchFilter".equals(event.getEventName()) || !config.registerBankTags())
		{
			return;
		}
		bankTags.filterSearch(client.getIntStack(), client.getIntStackSize(),
			client.getObjectStack(), client.getObjectStackSize());
	}

