/**
 * An item a step asks for, with every id that would satisfy it.
 *
 * <p>A category word carries many: "Pickaxe" is every pickaxe, so whichever
 * one the player owns counts. An unresolved name carries none, and is never
 * reported as missing.
 */
public class ItemRef
{
	private String name;
	private List<Integer> ids;
	private int count;

	public String getName()
	{
		return name;
	}

	public List<Integer> getIds()
	{
		return ids == null ? Collections.emptyList() : ids;
	}

	public boolean isResolved()
	{
		return !getIds().isEmpty();
	}

	/**
	 * How many the step asks for; 1 when the guide does not say.
	 *
	 * <p>Absent means one, not unknown -- "Buy 5 Jugs of wine" must not be
	 * satisfied by a single jug.
	 */
	public int getCount()
	{
		return count < 1 ? 1 : count;
	}
}

